package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.CommandLineParser;
import org.apache.commons.cli.DefaultParser;
import org.apache.commons.cli.Options;
import org.apache.commons.cli.ParseException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class OptionBuilder_create_TriageGen0Test {

    private OptionBuilder optionBuilder;

    @Before
    public void setUp() {
        optionBuilder = OptionBuilder.withLongOpt("longopt")
                .withDescription("description")
                .hasArg()
                .withArgName("argName")
                .isRequired()
                .withValueSeparator('=')
                .withType(String.class);
    }

    @Test
    public void testCreate_ValidOption() throws IllegalArgumentException {
        Option option = OptionBuilder.create("o");
        assertNotNull(option);
        assertTrue(option.hasArg());
        assertEquals("longopt", option.getLongOpt());
        assertEquals("description", option.getDescription());
        assertEquals("argName", option.getArgName());
        assertTrue(option.isRequired());
        assertEquals("=", option.getValueSeparator());
        assertEquals(String.class, option.getType());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_NullOption() throws IllegalArgumentException {
        OptionBuilder.create(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_EmptyOption() throws IllegalArgumentException {
        OptionBuilder.create("");
    }

    @Test
    public void testCreate_WithCustomProperties() throws IllegalArgumentException {
        optionBuilder.hasOptionalArg().withArgs(2).withType(Integer.class);
        Option option = OptionBuilder.create("o");
        assertNotNull(option);
        assertTrue(option.hasOptionalArg());
        assertEquals(2, option.getArgs());
        assertEquals(Integer.class, option.getType());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_InvalidType() throws IllegalArgumentException {
        OptionBuilder.create("o").withType(new Object());
    }

    @Test
    public void testCreate_DefaultProperties() throws IllegalArgumentException {
        Option option = OptionBuilder.create("o");
        assertNull(option.getLongOpt());
        assertNull(option.getArgName());
        assertFalse(option.isRequired());
        assertNull(option.getValueSeparator());
        assertNull(option.getType());
    }

    @Test
    public void testCreate_WithResetProperties() throws IllegalArgumentException, ParseException {
        Option option1 = OptionBuilder.create("o");
        Option option2 = OptionBuilder.create("o");

        assertFalse(option1.equals(option2));

        optionBuilder.reset();
        Option option3 = OptionBuilder.create("o");

        assertTrue(option1.equals(option3));
    }

    @Test
    public void testCreate_WithCommandLineParser() throws ParseException {
        Option option = OptionBuilder.create("o");
        Options opts = new Options();
        opts.addOption(option);

        CommandLineParser parser = new DefaultParser();
        String[] args = {"-o=arg"};
        org.apache.commons.cli.CommandLine cmd = parser.parse(opts, args);

        assertEquals("arg", cmd.getOptionValue("o"));
    }

    @Test
    public void testCreate_WithShortOption() throws IllegalArgumentException {
        Option option = OptionBuilder.create("o");
        assertTrue(option.hasArg());
        assertEquals("o", option.getOpt());
    }
}
